```python
def calcular_media_semestral():
    """
    Calcula e imprime a média semestral de duas notas válidas.
    """
    try:
        nota1 = float(input())
        nota2 = float(input())

        if nota1 < 0 or nota2 < 0:
            print("nota invalida")
        else:
            media = (nota1 + nota2) / 2
            print("media = " + str(media))

    except ValueError:
        print("nota invalida")

if __name__ == "__main__":
    calcular_media_semestral()
```

```java
import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4};
        int sum = sumEvenNumbers(numbers);
        System.out.println(sum); // Saída: 6
    }

    public static int sumEvenNumbers(int[] numbers) {
        int sum = 0;
        for (int number : numbers) {
            if (number % 2 == 0) {
                sum += number;
            }
        }
        return sum;
    }
}
```

```java
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> lista = new ArrayList<>();
        lista.add(1);
        lista.add(2);
        lista.add(3);
        lista.add(4);
        System.out.println(somaPares(lista));
    }

    public static int somaPares(List<Integer> lista) {
        int soma = 0;
        for (Integer num : lista) {
            if (num % 2 == 0) {
                soma += num;
            }
        }
        return soma;
    }
}
```

```java
import java.util.List;

class Solution {
    /**
     * Calcula a soma dos números pares em uma lista de inteiros.
     *
     * @param numbers A lista de inteiros.
     * @return A soma dos números pares na lista.
     */
    public int sumOfEvenNumbers(List<Integer> numbers) {
        int sum = 0;
        for (int number : numbers) {
            if (number % 2 == 0) {
                sum += number;
            }
        }
        return sum;
    }
}
```

```java
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double nota1 = 0, nota2 = 0;
        boolean valid = false;

        while (!valid) {
            System.out.print("Digite a primeira nota: ");
            nota1 = scanner.nextDouble();

            if (nota1 < 0 || nota1 > 10) {
                System.out.println("nota invalida");
            } else {
                valid = true;
            }
        }

        valid = false;

        while (!valid) {
            System.out.print("Digite a segunda nota: ");
            nota2 = scanner.nextDouble();

            if (nota2 < 0 || nota2 > 10) {
                System.out.println("nota invalida");
            } else {
                valid = true;
            }
        }

        double media = (nota1 + nota2) / 2.0;
        System.out.printf("media = %.2f\n", media);
    }
}
```

```java
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        double nota1 = 0;
        double nota2 = 0;
        boolean valida1 = false;
        boolean valida2 = false;

        while (true) {
            System.out.print("Nota 1 (0-10): ");
            double nota1Temp = scanner.nextDouble();
            if (nota1Temp >= 0 && nota1Temp <= 10) {
                valida1 = true;
                nota1 = nota1Temp;
            } else {
                System.out.println("Nota invalida");
            }

            System.out.print("Nota 2 (0-10): ");
            double nota2Temp = scanner.nextDouble();
            if (nota2Temp >= 0 && nota2Temp <= 10) {
                valida2 = true;
                nota2 = nota2Temp;
            } else {
                System.out.println("Nota invalida");
            }

            if (valida1 && valida2) {
                break;
            }
        }

        if (valida1 && valida2) {
            double media = (nota1 + nota2) / 2;
            System.out.println("Media = " + String.format("%.2f", media));
        }
    }
}
```

```java
import java.util.Scanner;

public class MediaSemestral {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int nota1, nota2;

        System.out.print("Digite a primeira nota: ");
        nota1 = scanner.nextInt();

        System.out.print("Digite a segunda nota: ");
        nota2 = scanner.nextInt();

        if (nota1 < 0 || nota2 < 0) {
            System.out.println("nota invalida");
        } else {
            double media = (double) (nota1 + nota2) / 2;
            System.out.println("media = " + media);
        }
    }
}
```

